import React, { useState } from 'react'
import { FiStar, FiUsers, FiCalendar, FiArchive, FiTrash2, FiMenu } from 'react-icons/fi'

import { Container, GroupsContainer, GroupItem, GroupHeader } from './styles'

import { IconButton } from '../../styles/global'

const groups = ['Personal', 'Work', 'Projects', 'Ideas', 'Important']

const VerticalBar: React.FC = () => {
  const [menuExpanded, setMenuExpanded] = useState(false)
  const [groupsExpanded, setGroupsExpanded] = useState(false)

  const expanded = menuExpanded || groupsExpanded
  return (
    <Container expanded={expanded}>
      <IconButton expanded={expanded} title="Menu" onClick={() => setMenuExpanded(!expanded)}>
        <FiMenu />
        {expanded && <span>Menu</span>}
      </IconButton>

      <IconButton expanded={expanded} title="Favorites">
        <FiStar />
        {expanded && <span>Favorites</span>}
      </IconButton>

      <GroupHeader
        expanded={expanded}
        title="Groups"
        onClick={() => setGroupsExpanded(!groupsExpanded)}
      >
        <FiUsers />
        {expanded && <span>Groups</span>}
      </GroupHeader>

      {groupsExpanded && (
        <GroupsContainer>
          {groups.map((group) => (
            <GroupItem key={group}>{group}</GroupItem>
          ))}
        </GroupsContainer>
      )}

      <IconButton expanded={expanded} title="Calendar">
        <FiCalendar />
        {expanded && <span>Calendar</span>}
      </IconButton>

      <IconButton expanded={expanded} title="Archive">
        <FiArchive />
        {expanded && <span>Archive</span>}
      </IconButton>

      <IconButton expanded={expanded} title="Trash">
        <FiTrash2 />
        {expanded && <span>Trash Bin</span>}
      </IconButton>
    </Container>
  )
}

export default VerticalBar
